/**
 * @method
 * @name scwin.openInfo
 * @author Inswave
 * @date 2026. 09. 29
 * @param img div
 * @returns
 * @hidden N
*/
scwin.openInfo = function (img, div) {
    /* sdd-asis-lifecycle:begin openInfo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (function() {
            const divObj = eval("document.all." + div + "Div");
            if (divObj.style.display === "none") {
                img.setSrc("/img/filing/btn/btn_closew.gif");
                divObj.style.display = "block";
            } else {
                img.setSrc("/img/filing/btn/btn_openw.gif");
                divObj.style.display = "none";
            }
        }());
    /* sdd-asis-lifecycle:end */
};


